import { motion } from "framer-motion";
import "../App.css";

function Hero() {
  const fadeUp = {
    hidden: { opacity: 0, y: 40 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.8, ease: "easeOut" } },
  };

  const staggerContainer = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
      },
    },
  };

  return (
    <main
      style={{
        minHeight: "100vh",
        background: "#0a0a0a",
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Hero Section */}
      <motion.div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "100px",
          maxWidth: "1600px",
          margin: "0 auto",
          padding: "140px 80px 160px",
          alignItems: "center",
        }}
        initial="hidden"
        animate="visible"
        variants={staggerContainer}
      >
        {/* Left Content */}
        <motion.div variants={fadeUp}>
          <div style={{
            display: "inline-block",
            padding: "8px 20px",
            background: "rgba(255, 107, 53, 0.1)",
            border: "1px solid rgba(255, 107, 53, 0.2)",
            borderRadius: "30px",
            marginBottom: "40px"
          }}>
            <span style={{
              fontSize: "13px",
              fontWeight: "600",
              color: "#ff6b35",
              letterSpacing: "1px",
              textTransform: "uppercase"
            }}>
              Professional Design Platform
            </span>
          </div>

          <h1
            style={{
              fontSize: "clamp(3rem, 5vw, 5.5rem)",
              fontWeight: 900,
              color: "#fff",
              marginBottom: "30px",
              lineHeight: "1.1",
              letterSpacing: "-2.5px",
            }}
          >
            AI-driven Interior
            <br />
            <span style={{
              background: "linear-gradient(135deg, #ff6b35 0%, #ff4d00 100%)",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              backgroundClip: "text"
            }}>
              Proposals in Minutes
            </span>
          </h1>

          <p
            style={{
              fontSize: "clamp(1.1rem, 2vw, 1.4rem)",
              color: "rgba(255, 255, 255, 0.7)",
              marginBottom: "50px",
              lineHeight: "1.8",
              letterSpacing: "-0.3px",
              fontWeight: "400"
            }}
          >
            ASSEMBLE은 사용자의 요청사항에 맞게
            <br />
            AI 기반 인테리어를 추천합니다
          </p>

          <div style={{ display: "flex", gap: "20px", flexWrap: "wrap" }}>
            <motion.button
              style={{
                padding: "20px 50px",
                fontSize: "1.15rem",
                fontWeight: 700,
                border: "none",
                borderRadius: "15px",
                background: "linear-gradient(135deg, #ff6b35 0%, #ff4d00 100%)",
                color: "#fff",
                cursor: "pointer",
                transition: "all 0.3s ease",
                boxShadow: "0 10px 30px rgba(255, 107, 53, 0.4)",
                letterSpacing: "-0.3px"
              }}
              whileHover={{ 
                scale: 1.05,
                boxShadow: "0 15px 40px rgba(255, 107, 53, 0.5)"
              }}
              whileTap={{ scale: 0.95 }}
            >
              Get Started
            </motion.button>

            <motion.button
              style={{
                padding: "20px 50px",
                fontSize: "1.15rem",
                fontWeight: 700,
                border: "2px solid rgba(255, 255, 255, 0.2)",
                borderRadius: "15px",
                background: "rgba(255, 255, 255, 0.05)",
                backdropFilter: "blur(10px)",
                color: "#fff",
                cursor: "pointer",
                transition: "all 0.3s ease",
                letterSpacing: "-0.3px"
              }}
              whileHover={{ 
                background: "rgba(255, 255, 255, 0.1)",
                borderColor: "rgba(255, 255, 255, 0.3)"
              }}
              whileTap={{ scale: 0.95 }}
            >
              Learn More
            </motion.button>
          </div>
        </motion.div>

        {/* Right Image */}
        <motion.div
          variants={fadeUp}
          style={{
            borderRadius: "24px",
            overflow: "hidden",
            boxShadow: "0 30px 90px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(255, 255, 255, 0.08)",
            position: "relative"
          }}
        >
          <div style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: "linear-gradient(135deg, rgba(255, 107, 53, 0.15) 0%, transparent 100%)",
            zIndex: 1
          }} />
          <img
            src="https://image.hanssem.com/hsimg/upload/homeIdea/2025/10/15/1760508599558_057278.jpg?w=1500"
            alt="Interior Design"
            style={{
              width: "100%",
              height: "650px",
              objectFit: "cover",
              display: "block",
            }}
          />
        </motion.div>
      </motion.div>

      {/* Features Section */}
      <motion.div
        style={{
          background: "linear-gradient(180deg, #0a0a0a 0%, #141414 100%)",
          padding: "140px 80px",
          borderTop: "1px solid rgba(255, 255, 255, 0.08)"
        }}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true }}
        variants={staggerContainer}
      >
        <div style={{ maxWidth: "1600px", margin: "0 auto" }}>
          <motion.div variants={fadeUp} style={{ textAlign: "center", marginBottom: "90px" }}>
            <h2
              style={{
                fontSize: "clamp(2.5rem, 4vw, 3.5rem)",
                fontWeight: 800,
                color: "#fff",
                marginBottom: "20px",
                letterSpacing: "-1.5px"
              }}
            >
              디자이너를 위한 혁신적인 기능
            </h2>
            <p style={{
              fontSize: "1.15rem",
              color: "rgba(255, 255, 255, 0.6)",
              letterSpacing: "-0.3px"
            }}>
              전문가를 위한 프로페셔널 인테리어 솔루션
            </p>
          </motion.div>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))",
              gap: "30px",
            }}
          >
            {[
              {
                icon: "fas fa-magic",
                title: "AI 자동 생성",
                description: "최첨단 AI 기술로 당신만의 맞춤형 인테리어를 즉시 생성합니다",
                gradient: "linear-gradient(155deg, #fff 20%, #ff4d00 100%)",
              },
              {
                icon: "fas fa-clock",
                title: "빠른 디자인",
                description: "몇 분 안에 다양한 스타일의 인테리어 시안을 확인하세요",
                gradient: "linear-gradient(155deg, #fff 20%, #ff4d00 100%)",
              },
              {
                icon: "fas fa-palette",
                title: "무한한 아이디어",
                description: "다양한 컨셉과 스타일로 당신의 공간을 완벽하게 연출합니다",
                gradient: "linear-gradient(155deg, #fff 20%, #ff4d00 100%)",
              },
              {
                icon: "fas fa-chart-line",
                title: "프로젝트 관리",
                description: "진행 중인 모든 프로젝트를 한눈에 관리하고 추적하세요",
                gradient: "linear-gradient(155deg, #fff 20%, #ff4d00 100%)",
              },
            ].map((feature, index) => (
              <motion.div
                key={index}
                style={{
                  background: "rgba(255, 255, 255, 0.03)",
                  backdropFilter: "blur(20px)",
                  padding: "50px 35px",
                  borderRadius: "20px",
                  border: "1px solid rgba(255, 255, 255, 0.08)",
                  textAlign: "center",
                  cursor: "pointer",
                  transition: "all 0.4s cubic-bezier(0.22, 1, 0.36, 1)",
                  position: "relative",
                  overflow: "hidden"
                }}
                variants={fadeUp}
                whileHover={{
                  y: -12,
                  background: "rgba(255, 255, 255, 0.06)",
                  borderColor: "rgba(255, 107, 53, 0.3)",
                }}
              >
                <div 
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    background: "linear-gradient(135deg, rgba(255, 107, 53, 0.05) 0%, transparent 100%)",
                    opacity: 0,
                    transition: "opacity 0.4s ease",
                    pointerEvents: "none"
                  }}
                />
                
                <motion.div
                  style={{
                    width: "90px",
                    height: "90px",
                    margin: "0 auto 30px",
                    borderRadius: "20px",
                    background: feature.gradient,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    boxShadow: "0 15px 40px rgba(255, 107, 53, 0.3)",
                  }}
                  whileHover={{ rotate: 360, scale: 1.1 }}
                  transition={{ duration: 0.6 }}
                >
                  <i className={feature.icon} style={{ fontSize: "2.5em", color: "#fff" }}></i>
                </motion.div>

                <h3
                  style={{
                    fontSize: "1.5rem",
                    fontWeight: 700,
                    color: "#fff",
                    marginBottom: "16px",
                    letterSpacing: "-0.5px"
                  }}
                >
                  {feature.title}
                </h3>

                <p
                  style={{
                    fontSize: "1.05rem",
                    color: "rgba(255, 255, 255, 0.65)",
                    lineHeight: "1.7",
                    margin: 0,
                    letterSpacing: "-0.2px"
                  }}
                >
                  {feature.description}
                </p>
              </motion.div>
            ))}
          </div>
        </div>
      </motion.div>

      {/* Stats Section */}
      <motion.div
        style={{
          padding: "120px 80px",
          maxWidth: "1600px",
          margin: "0 auto",
          background: "#0a0a0a"
        }}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true }}
        variants={staggerContainer}
      >
        <div
          style={{
            display: "flex",
            justifyContent: "space-around",
            flexWrap: "wrap",
            gap: "60px",
            background: "rgba(255, 255, 255, 0.03)",
            backdropFilter: "blur(20px)",
            padding: "90px 60px",
            borderRadius: "25px",
            border: "1px solid rgba(255, 255, 255, 0.08)",
          }}
        >
          {[
            { value: "10,000+", label: "완성된 프로젝트" },
            { value: "5,000+", label: "만족한 사용자" },
            { value: "50+", label: "디자인 스타일" },
            { value: "99%", label: "고객 만족도" },
          ].map((stat, index) => (
            <motion.div
              key={index}
              style={{ textAlign: "center" }}
              variants={fadeUp}
              whileHover={{ scale: 1.08 }}
              transition={{ duration: 0.3 }}
            >
              <h2
                style={{
                  fontSize: "clamp(3rem, 5vw, 4.5rem)",
                  fontWeight: 900,
                  background: "linear-gradient(135deg, #ff6b35 0%, #ff4d00 100%)",
                  WebkitBackgroundClip: "text",
                  WebkitTextFillColor: "transparent",
                  backgroundClip: "text",
                  marginBottom: "15px",
                  letterSpacing: "-2px"
                }}
              >
                {stat.value}
              </h2>
              <p
                style={{
                  fontSize: "1.15rem",
                  color: "rgba(255, 255, 255, 0.7)",
                  margin: 0,
                  fontWeight: 600,
                  letterSpacing: "-0.3px"
                }}
              >
                {stat.label}
              </p>
            </motion.div>
          ))}
        </div>
      </motion.div>
    </main>
  );
}

export default Hero;
